import type {Rect} from './types'
import type {LinearImageRows} from '../image-row-source'

/** Both independent axes were generated by the original Rust bilinear sampler.
 * Include each valid cell and its right/bottom neighbour before rebasing.
 * Alignment lets adjacent tiles and AA phases share immutable source texels. */
export function sourceImageWindow(axes:Float32Array, target:Rect, width:number, height:number, alignment: 1 | 256 = 256):Rect|undefined {
  const span=Math.max(target.w,target.h)
  if(axes.length!==span*8||!Number.isSafeInteger(width)||!Number.isSafeInteger(height)||width<1||height<1)return
  const range=(axis:number,count:number,size:number)=>{
    let lo=size,hi=-1
    for(let i=0;i<count;i++){
      const at=(axis*span+i)*4
      if(axes[at+3]!==-1)return
      if(axes[at+2]===0)continue
      const cell=axes[at]
      if(axes[at+2]!==1||!Number.isInteger(cell)||cell< -1||cell>=size)return
      lo=Math.min(lo,Math.max(0,cell));hi=Math.max(hi,Math.min(size-1,cell+1))
    }
    if(hi<0)return [0,1]
    return [Math.floor(lo/alignment)*alignment,Math.min(size,Math.ceil((hi+1)/alignment)*alignment)]
  }
  const x=range(0,target.w,width),y=range(1,target.h,height)
  if(!x||!y)return
  const w=x[1]-x[0],h=y[1]-y[0]
  if(w*h>524288||w*h*4>width*height)return
  return {x:x[0],y:y[0],w,h}
}

export function copySourceWindow(image:{width:number;height:number;pixels:Float32Array;linearRows?:()=>LinearImageRows;linearWindow?:(x:number,y:number,w:number,h:number)=>Float32Array}, window:Rect){
  const {x,y,w,h}=window
  if(x<0||y<0||w<1||h<1||x+w>image.width||y+h>image.height)throw Error('Invalid source image window')
  if(image.linearWindow){
    const pixels=image.linearWindow(x,y,w,h)
    if(pixels.length!==w*h*4)throw Error('Incomplete source image window')
    return pixels
  }
  const result=new Float32Array(w*h*4)
  const rows=image.linearRows?.()??[{y:0,height:image.height,pixels:image.pixels}]
  let next=0,copied=0
  for(const row of rows){
    if(row.y!==next||row.height<1||row.pixels.length!==image.width*row.height*4)throw Error('Invalid source image rows')
    next+=row.height
    for(let iy=Math.max(y,row.y);iy<Math.min(y+h,next);iy++){
      const start=((iy-row.y)*image.width+x)*4
      result.set(row.pixels.subarray(start,start+w*4),(iy-y)*w*4);copied++
    }
    if(next>=y+h)break
  }
  if(copied!==h)throw Error('Incomplete source image window')
  return result
}

/** The four native sampling phases must share the complete bilinear footprint. */
export function magnifiedImageWindow(planes: Float32Array[], target: Rect, width: number, height: number): Rect | undefined {
  if (planes.length !== 4) return
  let left = width, top = height, right = 0, bottom = 0
  for (const plane of planes) {
    const crop = sourceImageWindow(plane, target, width, height, 1)
    if (!crop) return
    left = Math.min(left, crop.x)
    top = Math.min(top, crop.y)
    right = Math.max(right, crop.x + crop.w)
    bottom = Math.max(bottom, crop.y + crop.h)
  }
  const area = (right - left) * (bottom - top)
  if (area > 16384 || area * 16 >= target.w * target.h) return
  return {x: left, y: top, w: right - left, h: bottom - top}
}

/** WebGPU's straight source path uses Rust's 256 RGB and 256 alpha words.
 * Round the same premultiplication once when storing each f32 source texel. */
export function linearSrgbWindow(bytes: Uint8Array, width: number, height: number, crop: Rect, lut: Float32Array) {
  if (lut.length !== 512 || bytes.length !== width * height * 4 ||
      ![crop.x, crop.y, crop.w, crop.h].every(Number.isSafeInteger) ||
      crop.x < 0 || crop.y < 0 || crop.w < 1 || crop.h < 1 ||
      crop.x + crop.w > width || crop.y + crop.h > height || crop.w * crop.h > 16384) throw Error('Invalid straight source window')
  let pixels: Float32Array | undefined, dest = 0
  for (let y = crop.y; y < crop.y + crop.h; y++) {
    let src = (y * width + crop.x) * 4
    for (let x = 0; x < crop.w; x++, src += 4, dest += 4) {
      const alpha = lut[256 + bytes[src + 3]]
      if (alpha === 0) continue
      pixels ??= new Float32Array(crop.w * crop.h * 4)
      pixels[dest] = lut[bytes[src]] * alpha
      pixels[dest + 1] = lut[bytes[src + 1]] * alpha
      pixels[dest + 2] = lut[bytes[src + 2]] * alpha
      pixels[dest + 3] = alpha
    }
  }
  return pixels ?? null
}
